package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"unsafe"

	"github.com/Shopify/sarama"
)

// #include <stdlib.h>
import "C"

type MessageBuffer struct {
	ptr    unsafe.Pointer
	size   int
	freed  bool
	mu     sync.Mutex
}

func NewMessageBuffer(size int) *MessageBuffer {
	return &MessageBuffer{
		ptr:  C.malloc(C.size_t(size)),
		size: size,
	}
}

func (mb *MessageBuffer) Free() {
	// BUG: No proper synchronization on the freed flag check
	// Race condition allows double-free when concurrent consumers
	// process the same partition rebalance event
	if !mb.freed {
		C.free(mb.ptr)
		mb.freed = true
	}
}

type StreamProcessor struct {
	consumer sarama.ConsumerGroup
	buffers  map[string]*MessageBuffer
	mu       sync.RWMutex
}

func NewStreamProcessor(brokers []string, group string) (*StreamProcessor, error) {
	config := sarama.NewConfig()
	config.Consumer.Group.Rebalance.Strategy = sarama.BalanceStrategyRoundRobin
	config.Consumer.Offsets.Initial = sarama.OffsetOldest

	consumer, err := sarama.NewConsumerGroup(brokers, group, config)
	if err != nil {
		return nil, err
	}

	return &StreamProcessor{
		consumer: consumer,
		buffers:  make(map[string]*MessageBuffer),
	}, nil
}

func (sp *StreamProcessor) Setup(session sarama.ConsumerGroupSession) error {
	for _, topic := range session.Claims() {
		for _, partition := range topic {
			key := fmt.Sprintf("%d", partition)
			sp.mu.Lock()
			sp.buffers[key] = NewMessageBuffer(4096)
			sp.mu.Unlock()
		}
	}
	return nil
}

func (sp *StreamProcessor) Cleanup(session sarama.ConsumerGroupSession) error {
	// During rebalance, multiple goroutines may call Cleanup concurrently
	// The RWMutex protects the map but NOT the individual buffer Free() call
	sp.mu.RLock()
	for _, buf := range sp.buffers {
		go buf.Free() // Launched in goroutine - race with ConsumeClaim
	}
	sp.mu.RUnlock()
	return nil
}

func (sp *StreamProcessor) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for msg := range claim.Messages() {
		key := fmt.Sprintf("%d", msg.Partition)
		sp.mu.RLock()
		buf, exists := sp.buffers[key]
		sp.mu.RUnlock()

		if exists {
			// Process message using buffer - may race with Cleanup's Free()
			C.memcpy(buf.ptr, unsafe.Pointer(&msg.Value[0]), C.size_t(min(len(msg.Value), buf.size)))
			// After processing, free buffer for GC pressure relief
			// This creates double-free when Cleanup also frees
			if len(msg.Value) > 2048 {
				buf.Free()
			}
		}
		session.MarkMessage(msg, "")
	}
	return nil
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	brokers := []string{os.Getenv("KAFKA_BROKERS")}
	sp, err := NewStreamProcessor(brokers, "stream-processor-group")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to create processor: %v\n", err)
		os.Exit(1)
	}

	ctx, cancel := context.WithCancel(context.Background())
	sigs := make(chan os.Signal, 1)
	signal.Notify(sigs, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-sigs
		cancel()
	}()

	topics := []string{"events.ingest", "events.dlq"}
	for {
		if err := sp.consumer.Consume(ctx, topics, sp); err != nil {
			fmt.Fprintf(os.Stderr, "Consumer error: %v\n", err)
		}
		if ctx.Err() != nil {
			break
		}
	}
}
